import * as React from 'react'
import { QRCodeSVG, QRCodeCanvas } from 'qrcode.react'
import { Download, RefreshCw } from 'lucide-react'
import { cn } from '@/lib/utils'
import { Button } from '@/components/ui/button'
export function QRCode({
  value,
  size = 160,
  level = 'M',
  className,
  color = '#202124',
  background = '#ffffff',
  status = 'active',
  onRefresh,
  downloadable = false,
  downloadFormat = 'svg',
  icon,
}: {
  value: string
  size?: number
  level?: 'L' | 'M' | 'Q' | 'H'
  className?: string
  color?: string
  background?: string
  status?: 'active' | 'loading' | 'expired' | 'scanned'
  onRefresh?: () => void
  downloadable?: boolean
  downloadFormat?: 'svg' | 'png'
  icon?: string
}) {
  const ref = React.useRef<HTMLDivElement>(null)
  const download = () => {
    if (downloadFormat === 'png') {
      const canvas = ref.current?.querySelector('canvas')
      if (canvas) {
        const link = document.createElement('a')
        link.href = canvas.toDataURL('image/png')
        link.download = 'qr-code.png'
        link.click()
      }
      return
    }
    const svg = ref.current?.querySelector('svg')
    if (!svg) return
    const url = URL.createObjectURL(
      new Blob([new XMLSerializer().serializeToString(svg)], { type: 'image/svg+xml' }),
    )
    const a = document.createElement('a')
    a.href = url
    a.download = 'qr-code.svg'
    a.click()
    setTimeout(() => URL.revokeObjectURL(url), 1000)
  }
  return (
    <div className="inline-flex flex-col items-center gap-3">
      <div
        ref={ref}
        className={cn('relative inline-flex rounded-xl border p-4', className)}
        style={{ background }}
      >
        <QRCodeSVG
          title="QR code"
          value={value}
          size={size}
          level={level}
          bgColor={background}
          fgColor={color}
          marginSize={1}
          imageSettings={
            icon
              ? {
                  src: icon,
                  height: size * 0.18,
                  width: size * 0.18,
                  excavate: true,
                  crossOrigin: 'anonymous',
                }
              : undefined
          }
        />
        <QRCodeCanvas
          value={value}
          size={size * 2}
          level={level}
          bgColor={background}
          fgColor={color}
          marginSize={1}
          style={{ display: 'none' }}
          imageSettings={
            icon
              ? {
                  src: icon,
                  height: size * 0.36,
                  width: size * 0.36,
                  excavate: true,
                  crossOrigin: 'anonymous',
                }
              : undefined
          }
        />
        {status !== 'active' && (
          <div className="absolute inset-0 flex flex-col items-center justify-center gap-3 rounded-xl bg-background/90 backdrop-blur-[2px]">
            <span className="text-sm font-medium">
              {status === 'expired'
                ? 'Code expired'
                : status === 'loading'
                  ? 'Preparing your code…'
                  : 'Successfully scanned'}
            </span>
            {status === 'expired' && onRefresh && (
              <Button size="sm" variant="outline" onClick={onRefresh}>
                <RefreshCw />
                Refresh
              </Button>
            )}
          </div>
        )}
      </div>
      {downloadable && (
        <Button size="sm" variant="outline" onClick={download}>
          <Download />
          Download {downloadFormat.toUpperCase()}
        </Button>
      )}
    </div>
  )
}

import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

import * as React from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from '@/lib/utils'
import { Slot } from 'radix-ui'
import { Loader2 } from 'lucide-react'

const buttonVariants = cva(
  "inline-flex shrink-0 items-center justify-center gap-2 rounded-md text-sm font-medium whitespace-nowrap transition-all outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: 'bg-primary text-primary-foreground hover:bg-primary/90',
        destructive:
          'bg-destructive text-white hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:bg-destructive/60 dark:focus-visible:ring-destructive/40',
        outline:
          'border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:border-input dark:bg-input/30 dark:hover:bg-input/50',
        secondary: 'bg-secondary text-secondary-foreground hover:bg-secondary/80',
        ghost: 'hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50',
        link: 'text-primary underline-offset-4 hover:underline',
        soft: 'bg-primary/10 text-primary hover:bg-primary/15',
        success: 'bg-emerald-600 text-white hover:bg-emerald-700',
        warning: 'bg-amber-400 text-amber-950 hover:bg-amber-500',
        dashed:
          'border border-dashed bg-background text-foreground hover:border-primary hover:text-primary',
      },
      size: {
        default:
          'h-[var(--ergon-control-height,2.25rem)] px-4 py-[var(--ergon-control-py,0.5rem)] has-[>svg]:px-3',
        xs: "h-6 gap-1 rounded-md px-2 text-xs has-[>svg]:px-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: 'h-8 gap-1.5 rounded-md px-3 has-[>svg]:px-2.5',
        lg: 'h-10 rounded-md px-6 has-[>svg]:px-4',
        icon: 'size-9',
        'icon-xs': "size-6 rounded-md [&_svg:not([class*='size-'])]:size-3",
        'icon-sm': 'size-8',
        'icon-lg': 'size-10',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  },
)

/**
 * Composes button variants, loading state, and optional slot rendering. Compact-density styles travel with the installed source.
 */
function Button({
  className,
  variant = 'default',
  size = 'default',
  asChild = false,
  loading = false,
  children,
  ...props
}: React.ComponentProps<'button'> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
    loading?: boolean
  }) {
  const Comp = asChild ? Slot.Root : 'button'

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn(buttonVariants({ variant, size }), className)}
      aria-busy={loading || undefined}
      {...props}
      disabled={props.disabled || loading}
    >
      {asChild ? (
        children
      ) : (
        <>
          {loading && <Loader2 className="animate-spin" />}
          {children}
        </>
      )}
    </Comp>
  )
}

export { Button, buttonVariants }
